# Let's try a constructive approach using a heuristic/backtracking algorithm

import random
from collections import defaultdict, deque

def has_short_cycle(adj, max_len=5):
    """Check if graph has any cycle of length <= max_len"""
    n = len(adj)
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            v = queue.popleft()
            if dist[v] >= max_len:
                continue
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v] and dist[v] + dist[u] + 1 <= max_len + 1:
                    # Found a cycle
                    return True
    return False

def check_girth(adj):
    """Check the girth of the graph"""
    n = len(adj)
    min_cycle = n + 1
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            v = queue.popleft()
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v]:
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def try_construct(seed=0):
    random.seed(seed)
    n = 21

    # Start with empty graph
    adj = [set() for _ in range(n)]

    # We'll add edges greedily while respecting constraints
    # First, ensure minimum degree 3 for all vertices

    # List all possible edges
    all_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_edges)

    # Phase 1: ensure each vertex has degree at least 3
    for v in range(n):
        needed = 3
        random.shuffle(all_edges)
        for (i, j) in all_edges:
            if needed <= 0:
                break
            if i == v or j == v:
                u = j if i == v else i
                if u not in adj[v] and len(adj[u]) < 5 and len(adj[v]) < 5:
                    # Check if adding this edge creates a short cycle
                    # Temporarily add
                    adj[v].add(u)
                    adj[u].add(v)
                    if has_short_cycle(adj, 5):
                        adj[v].remove(u)
                        adj[u].remove(v)
                    else:
                        needed -= 1

    # Check degrees
    degrees = [len(adj[v]) for v in range(n)]
    print(f"After phase 1: min deg = {min(degrees)}, max deg = {max(degrees)}")
    print(f"Degrees: {degrees}")

    # Phase 2: add more edges to increase degrees where possible
    random.shuffle(all_edges)
    for (i, j) in all_edges:
        if len(adj[i]) >= 5 or len(adj[j]) >= 5:
            continue
        if j in adj[i]:
            continue
        # Check if adding creates short cycle
        adj[i].add(j)
        adj[j].add(i)
        if has_short_cycle(adj, 5):
            adj[i].remove(j)
            adj[j].remove(i)

    degrees = [len(adj[v]) for v in range(n)]
    print(f"After phase 2: min deg = {min(degrees)}, max deg = {max(degrees)}")
    print(f"Degrees: {degrees}")

    girth = check_girth(adj)
    print(f"Girth: {girth}")

    if min(degrees) >= 3 and max(degrees) <= 5 and girth >= 6:
        edges = []
        for i in range(n):
            for j in adj[i]:
                if i < j:
                    edges.append((i, j))
        return edges
    return None

for seed in range(20):
    result = try_construct(seed)
    if result:
        print(f"Found solution with seed {seed}!")
        print(f"Edges: {result}")
        break
    print("---")
